select t.metric, count(*) cells, count(*) filter (where agg.n is null) no_rows, count(*) filter (where agg.n>0 and agg.latest_reason is null) latest_null_reason, count(*) filter (where agg.n>0 and agg.latest_reason is not null) latest_has_reason
from t join analytics.metric_definition md on md.metric_name=t.metric
left join lateral (select count(*) n, (array_agg(is_null_reason order by period_end desc, period_start desc, period_label))[1] latest_reason from analytics.metric_value mv where mv.company_id=t.company_id and mv.metric_definition_id=md.id) agg on true
group by 1 order by 2 desc